    }
    if (profile.authType === "api_key" || profile.authType === "auth_token") {
      if (!profile.apiKey || typeof profile.apiKey !== "string" || profile.apiKey.trim() === "") {
        errors.push("API key is required for api_key and auth_token types");
      }
